"""build_table_system.py — 生成「系统命令表」(任何领域都生效)

当前内容:
  vad_calibrate  ← 调整静音判定 / 静音窗 等（现场校准静音窗）
  show_commands  ← 命令列表 / 有哪些命令 / 能做什么 …（打开一份命令清单文件）
用法: python -m opencode_fastpath.build_table_system
"""
from __future__ import annotations

import json
from pathlib import Path

from .fastpath import FastPath
from .pinyin import Encoder

HERE = Path(__file__).resolve().parent
OUT = HERE / "table_system.json"

SYSTEM = [
    ("vad_calibrate", None, ["调整静音判定", "静音判定", "校准静音", "调整静音窗",
                             "静音窗", "调整静音", "静音判定校准", "重新校准静音"]),
    ("show_commands", None, ["命令列表", "命令清单", "有哪些命令", "有什么命令",
                             "能做什么", "能干什么", "能说哪些话", "有什么功能",
                             "使用说明", "怎么用"]),
]


def main():
    fp = FastPath(table_path=OUT, mode="off")
    fp.entries = []
    fp.enc = Encoder()
    n = 0
    for intent, arg, trig in SYSTEM:
        fp.install(intent, arg, trig, additive=True, markers={"source": "system"})
        n += len(trig)
    st = fp.stats()
    print(f"[OPENCODE] 系统命令表: 条目 {len(fp.entries)} 触发词 {n} "
          f"行(全串/前缀) {st['full']}/{st['prefix']} → {OUT}")
    for t in ["调整静音判定", "校准静音"][:2]:
        r = fp.route_prefix(t, tail_only=True)
        print(f"   「{t}」 → {r['decision']} {r.get('intent') or ''}")


if __name__ == "__main__":
    main()
